const ALL = [];
LESSONS.forEach(function(L){ L.w.forEach(function(w){ w.li = L.n; ALL.push(w); }); });
const BD = '০১২৩৪৫৬৭৮৯';
const bn = function(n){ return String(n).replace(/\d/g, function(d){ return BD[d]; }); };
const LS = {
  get: function(k, d){ try{ var v = localStorage.getItem('n5v_' + k); return v == null ? d : JSON.parse(v); }catch(e){ return d; } },
  set: function(k, v){ try{ localStorage.setItem('n5v_' + k, JSON.stringify(v)); }catch(e){} }
};
var learned = new Set(LS.get('learned', []));
function saveLearned(){ LS.set('learned', Array.from(learned)); }
function speak(t){
  if(!('speechSynthesis' in window) || !t) return;
  speechSynthesis.cancel();
  var u = new SpeechSynthesisUtterance(t); u.lang = 'ja-JP'; u.rate = 0.9; speechSynthesis.speak(u);
}
function el(tag, cls, text){ var e = document.createElement(tag); if(cls) e.className = cls; if(text != null) e.textContent = text; return e; }
function wordCard(w){
  var c = el('div', 'wc' + (learned.has(w.id) ? ' done' : ''));
  c.appendChild(el('div', 'k', w.k || w.r));
  if(w.k) c.appendChild(el('div', 'r', w.r));
  c.appendChild(el('div', 'm', w.b));
  if(w.s) c.appendChild(el('div', 's', w.s));
  if(w.sb) c.appendChild(el('div', 'sb', w.sb));
  var row = el('div', 'row');
  var sp = el('button', '', 'শুনুন'); sp.type = 'button';
  sp.addEventListener('click', function(){ speak(w.s || (w.k || w.r).replace(/\s*\[[^\]]*\]/g,'').replace(/[～~]/g,'')); });
  var lr = el('button', learned.has(w.id) ? 'on' : '', learned.has(w.id) ? 'শিখেছি' : 'শিখিনি'); lr.type = 'button';
  lr.addEventListener('click', function(){
    if(learned.has(w.id)) learned.delete(w.id); else learned.add(w.id);
    saveLearned(); route();
  });
  row.appendChild(sp); row.appendChild(lr); c.appendChild(row);
  return c;
}
function showHome(){
  document.getElementById('home').hidden = false;
  document.getElementById('view').hidden = true;
  var q = document.getElementById('q').value.trim().toLowerCase();
  var box = document.getElementById('lessons'); box.textContent = '';
  var tot = bn(ALL.length) + 'টি শব্দ · ' + bn(LESSONS.length) + 'টি পাঠ · শেখা হয়েছে ' + bn(learned.size);
  document.getElementById('tot').textContent = tot;
  if(q){
    document.getElementById('home').hidden = false;
    var res = ALL.filter(function(w){ return (w.k + ' ' + w.r + ' ' + w.b).toLowerCase().indexOf(q) !== -1; });
    var v = document.getElementById('view'); v.textContent = ''; v.hidden = false;
    v.appendChild(el('div', 'sub', res.length + 'টি শব্দ পাওয়া গেছে'));
    var g = el('div', 'cards'); res.forEach(function(w){ g.appendChild(wordCard(w)); }); v.appendChild(g);
    document.getElementById('lessons').textContent = '';
    return;
  }
  LESSONS.forEach(function(L){
    var n = L.w.filter(function(w){ return learned.has(w.id); }).length;
    var a = el('a', 'lcard'); a.href = '#L' + L.n;
    a.appendChild(el('b', '', 'পাঠ ' + bn(L.n) + ' · ' + L.t));
    a.appendChild(el('small', '', bn(L.w.length) + 'টি শব্দ · শেখা ' + bn(n)));
    var pr = el('div', 'pr'); var i = el('i'); i.style.width = (n / L.w.length * 100) + '%'; pr.appendChild(i); a.appendChild(pr);
    box.appendChild(a);
  });
}
function showLesson(n){
  var L = LESSONS.filter(function(x){ return x.n === n; })[0];
  if(!L){ location.hash = ''; return; }
  document.getElementById('home').hidden = true;
  var v = document.getElementById('view'); v.textContent = ''; v.hidden = false;
  var back = el('a', 'back', '← সব পাঠ'); back.href = '#';
  v.appendChild(back);
  v.appendChild(el('div', 'lt', 'পাঠ ' + bn(L.n) + ' · ' + L.t));
  var n2 = L.w.filter(function(w){ return learned.has(w.id); }).length;
  v.appendChild(el('div', 'lc', bn(L.w.length) + 'টি শব্দ · শেখা ' + bn(n2)));
  var g = el('div', 'cards'); L.w.forEach(function(w){ g.appendChild(wordCard(w)); }); v.appendChild(g);
  window.scrollTo(0, 0);
}
function route(){
  var m = location.hash.match(/^#L(\d+)$/);
  if(m) showLesson(parseInt(m[1], 10)); else showHome();
}
// stable ids
var id = 0;
LESSONS.forEach(function(L){ L.w.forEach(function(w){ w.id = ++id; }); });
document.getElementById('q').addEventListener('input', function(){ showHome(); });
function setTheme(t){
  document.documentElement.dataset.theme = t;
  document.querySelectorAll('[data-t]').forEach(function(b){ b.classList.toggle('on', b.dataset.t === t); });
  LS.set('theme', t);
}
document.querySelectorAll('[data-t]').forEach(function(b){ b.addEventListener('click', function(){ setTheme(b.dataset.t); }); });
setTheme(LS.get('theme', 'light'));
window.addEventListener('hashchange', route);
route();
